import{_ as t,o as n,c as a,a3 as r}from"./chunks/framework.BlfGB29P.js";const h=JSON.parse('{"title":"ATLAS in the Home Assistant frontend","description":"","frontmatter":{},"headers":[],"relativePath":"en/projects/atlas/frontend.md","filePath":"en/projects/atlas/frontend.md","lastUpdated":1793126212000}'),o={name:"en/projects/atlas/frontend.md"};function s(i,e,d,c,p,l){return n(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="atlas-in-the-home-assistant-frontend" tabindex="-1">ATLAS in the Home Assistant frontend <a class="header-anchor" href="#atlas-in-the-home-assistant-frontend" aria-label="Permalink to &quot;ATLAS in the Home Assistant frontend&quot;">​</a></h1><p>Since <strong>0.1.299</strong>, ATLAS provides the optional <strong>ATLAS Runtime</strong> integration. It registers its own HA administrator sidebar panel, opening Plugin Hub, Expert Card Editor and Administration from the existing runtime. The panel follows HA&#39;s DE/EN/FR language and light/dark appearance.</p><h2 id="requirements-and-data-preservation" tabindex="-1">Requirements and data preservation <a class="header-anchor" href="#requirements-and-data-preservation" aria-label="Permalink to &quot;Requirements and data preservation&quot;">​</a></h2><p>As of 2026-10-16: <strong>App 0.1.312</strong>, <strong>integration 0.1.306</strong>, versioned independently. Introduction and test versions below are not instructions to downgrade a newer App. Full HAOS recovery and deliberate address changes are covered in the <a href="./../atlas-plugins/file-studio">backup guide</a>; browser-local data still needs its own export.</p><p>ATLAS must already run as an App/Add-on, Docker container or <a href="/en/projects/atlas/linux">Linux/systemd service</a>. HACS installs the HA integration; the Node server and external plugins stay in their existing runtime. The add-on&#39;s existing Ingress entry is not replaced.</p><p>Back up HA before installing. Also export ATLAS projects and Administration settings in ATLAS. Keep the runtime&#39;s existing browser address: browser projects, cookies and encrypted settings are bound to the address or installation identity. Changing hostname, scheme or port does not automatically migrate data.</p><p>Browsers may also separate storage for an externally embedded runtime from its separately opened storage. If existing projects or encrypted settings are absent in the panel, use <strong>Open separately</strong> at the previous address and export them there; the integration does not move or delete those data. <a href="https://privacysandbox.google.com/cookies/storage-partitioning" target="_blank" rel="noreferrer">Storage partitioning reference</a>.</p><h2 id="hacs-installation" tabindex="-1">HACS installation <a class="header-anchor" href="#hacs-installation" aria-label="Permalink to &quot;HACS installation&quot;">​</a></h2><ol><li>Open HACS and its custom repositories.</li><li>Add <code>https://github.com/rockbaer2007/atlas</code> with type <strong>Integration</strong>.</li><li>Download <strong>ATLAS Runtime</strong> and restart Home Assistant.</li><li>Open <strong>Settings → Devices &amp; services → Add integration → ATLAS Runtime</strong>.</li><li>Enter the existing browser-accessible runtime base URL, for example <code>http://atlas-server:4176/</code> or <code>https://atlas.example.org/atlas/</code>.</li></ol><p>The integration does not request HA tokens or provider keys. Configure the HA connection in ATLAS Administration. Panel code does not send HA authentication or entity data to the embedded window. Ordinary HA state updates do not reload it.</p><p>This is a custom HACS repository; general HACS catalog inclusion is not claimed. Select repository type <strong>Integration</strong>, not Dashboard. Exported HACS card packages remain a separate workflow.</p><h3 id="hacs-reports-unknown-error" tabindex="-1">HACS reports “Unknown error” <a class="header-anchor" href="#hacs-reports-unknown-error" aria-label="Permalink to &quot;HACS reports “Unknown error”&quot;">​</a></h3><p>Check the corresponding entry in <strong>Settings → System → Logs</strong>. During the first Proxmox download, <code>hacs_repository_download</code> raised <code>AttributeError: &#39;NoneType&#39; object has no attribute &#39;data&#39;</code>: HACS could not find its repository entry before the package download began. Reload the HACS page, open <strong>ATLAS Runtime</strong> again and retry the download. In the verified case, the status then changed to <strong>Pending restart</strong>. This confirms the download; setup after restarting HA is a separate step. Other “Unknown error” causes require their corresponding log entry.</p><h2 id="shared-plugin-management-since-0-1-300" tabindex="-1">Shared plugin management since 0.1.300 <a class="header-anchor" href="#shared-plugin-management-since-0-1-300" aria-label="Permalink to &quot;Shared plugin management since 0.1.300&quot;">​</a></h2><p>App/Ingress and Runtime can store repository lists, imported plugin metadata and activation state in the same ATLAS server. Update the <strong>ATLAS App/runtime</strong> to 0.1.300 first; updating only the HACS integration is insufficient.</p><ol><li>Open the original <strong>ATLAS App access</strong> containing all your plugins.</li><li>Open Administration → Plugin Manager → <strong>Shared plugin management</strong>.</li><li>Choose <strong>Adopt local state</strong> and review repository/plugin/activation counts and listed conflicts.</li><li>Conflicts keep server values by default. Choose local values only when you deliberately want them adopted.</li><li>Click <strong>Back up and adopt</strong>. A download backs up plugin metadata; the server also backs up its previous state and incoming metadata before an atomic save.</li><li>Reopen Runtime or use <strong>Load server state</strong>. Subsequent changes are saved to the server; open Administration pages check every 15 seconds. Concurrent writes using an outdated revision are rejected.</li></ol><p>Empty adoption never removes existing server entries. Legacy local management remains valid until the first confirmed adoption, which does not delete old browser data. Unsaved changes receive a separate local recovery copy and can be previewed for adoption again. <strong>Inspect backup</strong> previews a metadata export or server snapshot; adoption merges entries.</p><p>State is stored at <code>ATLAS_PLUGIN_DATA_ROOT/.management/state.json</code>, with backups in <code>.management/backups/</code>. App/Add-on and Docker use the persistent plugin data directory. Include it in runtime backups. No packages are automatically installed or removed. HA tokens, provider keys, filesystem permissions, editor projects and settings owned by external plugins are outside this migration.</p><h2 id="shared-editor-projects-since-0-1-301" tabindex="-1">Shared editor projects since 0.1.301 <a class="header-anchor" href="#shared-editor-projects-since-0-1-301" aria-label="Permalink to &quot;Shared editor projects since 0.1.301&quot;">​</a></h2><p>Update the ATLAS App/runtime to <strong>0.1.301</strong>. Open the original App editor containing your project. Under <strong>Shared editor projects</strong>, choose <strong>New server project → Preview and save</strong>, review name and field count, then <strong>Back up and apply</strong>. Choose <strong>New server project</strong> again for another local project. Identical names are allowed and never automatically replace other projects.</p><p>In Runtime: <strong>Load project list</strong>, select the project, <strong>Preview opening</strong>, review and <strong>Back up and apply</strong>. Snapshots contain Expert fields and their Card configurations, project/script names, surface size and grid size. Save edits explicitly with <strong>Preview and save</strong>. Revision checks detect concurrent edits to the same project. Another browser never automatically replaces your workspace.</p><p>Before opening/saving, the current workspace is backed up to <code>ATLAS_PLUGIN_DATA_ROOT/.projects/workspaces/</code> and downloaded. Previous server states are in <code>.projects/backups/</code>; named projects use <code>.projects/projects.json</code>. Include the persistent plugin data directory in backups. <strong>Inspect backup</strong> previews a downloaded workspace backup. <strong>Inspect local draft</strong> recovers unsaved shared work from this browser; it is not automatically opened after a reload.</p><p>The original local project remains in its existing browser storage. Shared work uses a separate local draft. Settings, HA credentials, plugin management, palette favorites and external plugin projects are not transferred. Damaged server files are never replaced. Limits: 100 projects, 4 MiB per project and 64 MiB store size.</p><h2 id="manual-installation-and-updates" tabindex="-1">Manual installation and updates <a class="header-anchor" href="#manual-installation-and-updates" aria-label="Permalink to &quot;Manual installation and updates&quot;">​</a></h2><p>Copy only <code>custom_components/atlas_frontend</code> from the repository into <code>/config/custom_components/atlas_frontend</code>. Back up an existing directory before replacing it; retain other components. Restart HA and add the integration as above. <code>manifest.json</code> contains the version.</p><p>For HACS updates, update this integration and restart HA. Its runtime URL remains in the HA config entry. Update the ATLAS server independently through its existing deployment path. The integration&#39;s <strong>Configure</strong> action changes the address; export ATLAS data before a deliberate address change. Removing the integration removes its own panel access, not the ATLAS runtime, plugins or projects.</p><p>From integration <strong>0.1.306</strong>, migration checks reject unknown configuration schemas without rewriting the entry. The existing schema <strong>1.1</strong> is unchanged; package versions are independent of schema versions. Returning to an older integration is only qualified with a compatible schema. Back up HA configuration and ATLAS data before updates; a later schema change requires its matching data backup for recovery. An invalid stored runtime URL produces a setup error and can be corrected through <strong>Configure</strong>.</p><h2 id="http-https-and-embedding" tabindex="-1">HTTP, HTTPS and embedding <a class="header-anchor" href="#http-https-and-embedding" aria-label="Permalink to &quot;HTTP, HTTPS and embedding&quot;">​</a></h2><p>HTTPS HA needs an HTTPS runtime for embedding. An HTTP target displays guidance and <strong>Open separately</strong> instead. The base URL must not contain credentials, query parameters or fragments. Port 80 is valid; reverse-proxy prefixes are retained.</p><p>A reverse proxy must forward ATLAS subpaths correctly and permit framing from the HA origin. For a blank view, check <strong>Open separately</strong>, reachability, proxy routing and frame protection headers. Automatic discovery or persistent storage of an Ingress session address is outside this integration; continue using the add-on&#39;s existing Ingress access.</p><p>The panel&#39;s HA administrator requirement does not protect direct access to an external ATLAS server. Keep its existing access restrictions. The new panel uses <code>atlas-runtime</code> and does not replace another sidebar entry. Its module is served at <code>/atlas_frontend/frontend/atlas-homeassistant-panel.js</code>; it is not an additional Lovelace resource under <code>/hacsfiles/atlas/</code>.</p><h2 id="verified-scope" tabindex="-1">Verified scope <a class="header-anchor" href="#verified-scope" aria-label="Permalink to &quot;Verified scope&quot;">​</a></h2><p>Isolated checks use Home Assistant Core <strong>2026.10.1</strong>, a separate ATLAS runtime and fixture data. They cover config/options flows, the admin panel, reload, restart, static module and preservation of unrelated panels. HACS setup and embedding are verified on Proxmox/x86_64 and Pi 5/ARM64. The isolated integration cycle <strong>0.1.301 → 0.1.306</strong>, rollback to 0.1.301 and re-update preserve the same config entry and unrelated panels across real HA restarts. An unknown fixture schema is rejected without modifying its entry. On Pi 5 and Proxmox, the HACS update to 0.1.306, HA restart, panel, live entities and data preservation pass. The separate ATLAS App stays on 0.1.305 during this integration qualification.</p><p>The additional stable version <strong>2026.9.4</strong> is verified with integration and runtime <strong>0.1.306</strong> in a fresh isolated amd64 installation: config/options, integration reload, full HA restart, embedded Hub, Administration and Editor, authenticated version discovery and live entity selection. The config entry, unrelated panels, fixture project, plugin data and configuration file are preserved. Pi 5 and Proxmox were unchanged for this additional check. HACS download, Supervisor, ARM64 and integration rollback were not repeated on 2026.9.4.</p><p>On <strong>2026-10-21</strong>, the exact <strong>HA 2026.10.2</strong>, <strong>integration 0.1.306 / App 0.1.327</strong> combination is also qualified on test clone <strong>.68</strong>: embedded Hub, Administration and Editor, live connection/entity search, browser-local save/reload and JSON/YAML HACS bundles with <strong>112/112</strong> each and byte-identical export/import/re-export. After a real HA Core restart, the open Editor reconnects automatically without reloading. The original Editor, seven server projects, six plugins and captured settings/files are preserved; the temporary Runtime URL is restored. <strong>.177 is unchanged and was not accessed.</strong> Three full backups remain on .68. This is not an HA update, schema conversion or repeated HACS repository-installation/ARM64 qualification. HA retains the original URL as an explicit option; only administrative timestamps change otherwise.</p><p>The CI matrix includes eleven integration contracts per version for <strong>2026.9.4</strong>, <strong>2026.10.1</strong> and, since 2026-10-21, <strong>2026.10.2</strong>. This does not replace separate running-HA checks or establish an inclusive version range. Further HA versions and actual conversion between different data schemas remain separate qualification steps. All three CI rows pass; the 2026.10.2 contracts also pass locally in the official container with networking disabled. See the <a href="https://github.com/rockbaer2007/atlas/blob/main/docs/deployment/HA_COMPATIBILITY_MATRIX.md" target="_blank" rel="noreferrer">version matrix</a> for details and boundaries.</p><p>References: <a href="https://developers.home-assistant.io/docs/frontend/custom-ui/creating-custom-panels/" target="_blank" rel="noreferrer">HA custom panels</a> and <a href="https://www.hacs.xyz/docs/publish/integration/" target="_blank" rel="noreferrer">HACS integration structure</a>.</p>',37)])])}const u=t(o,[["render",s]]);export{h as __pageData,u as default};
